function getPowerbicopilotTranslation(key, lang) {
    if (powerbicopilotTranslations[lang] && powerbicopilotTranslations[lang][key]) {
        return powerbicopilotTranslations[lang][key];
    }
    if (powerbicopilotTranslations.en && powerbicopilotTranslations.en[key]) {
        return powerbicopilotTranslations.en[key];
    }
    return null;
}

function applyPowerbicopilotTranslations(lang) {
    console.log('Applying power-bi-copilot translations for:', lang);
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.power-bi-copilot.')) {
            const translation = getPowerbicopilotTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    console.log(`Applied ${count} power-bi-copilot translations`);
}

window.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyPowerbicopilotTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyPowerbicopilotTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyPowerbicopilotTranslations(currentLang);
}

console.log('power-bi-copilot i18n loaded');
